<script setup lang="ts">
import type { Day, Workout, StrengthWorkout, PlanState, Checkin } from '../api'
defineProps<{dates:{date:string;label:string}[];days:Day[];runs:Workout[];strength:StrengthWorkout[];checkins:Checkin[];plan:PlanState|null}>()
const labels={run:'跑步',strength:'力量',recovery:'休息 / 恢复'}
const status={completed:'完成',partial:'部分完成',skipped:'跳过'}
const emit=defineEmits<{feedback:[type:'run'|'strength',id:string]}>()
</script>
<template><div class="training-week"><p v-if="plan?.needs_review" class="error">身体反馈或日程已有变化，以下正式安排待重新评估，请先核对提示和新草稿。</p><article v-for="d in dates" :key="d.date" class="training-day"><div class="sectionhead"><h3>周{{d.label}} · {{d.date}}</h3><span class="tiny muted">{{days.find(a=>a.date===d.date)?.available?`可用 ${days.find(a=>a.date===d.date)?.duration_minutes} 分钟`:'无已确认训练窗口'}}</span></div><div class="training-columns"><div><h4>正式安排</h4><div v-for="s in plan?.plan?.sessions.filter(s=>s.date===d.date&&s.type!=='strength')||[]" :key="s.id" class="timeline-item"><span class="badge">{{labels[s.type]}}</span><p>{{s.title}}</p><p class="tiny muted">{{s.duration_minutes?`${s.duration_minutes} 分钟`:'无训练负荷'}} · {{plan?.plan?.is_mock?'已确认模拟模板':'已确认 AI 草稿'}}</p></div><p v-if="!plan?.plan?.sessions.some(s=>s.date===d.date&&s.type!=='strength')" class="tiny muted">无正式安排，待确认草稿不计入日历。</p></div><div><h4>实际记录</h4><div v-for="r in runs.filter(r=>r.date===d.date)" :key="r.id" class="timeline-item"><span class="badge">跑步 · 已记录</span><p>{{r.title}}</p><p class="tiny muted">{{(r.distance_m/1000).toFixed(2)}} km · {{Math.round(r.duration_seconds/60)}} 分钟</p><button class="textbtn" @click="emit('feedback','run',r.id)">补充这次跑步的身体反馈 →</button></div><p v-if="!runs.some(r=>r.date===d.date)&&!strength.some(s=>s.date===d.date)" class="tiny muted">无实际训练记录。没有记录不代表已漏练，也不会生成补练欠账。</p><p v-if="checkins.some(c=>c.date===d.date)" class="tiny muted">当天 {{checkins.filter(c=>c.date===d.date).length}} 条身体反馈</p></div></div></article></div></template>
